update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p031","body":"لبوں پہ ہنسی ، جگر میں داغ سا جلتا ہوا\nجہاں کہیں زندگی نے سفر لکھا، میں چلتا ہوا\n\nنظر سے دور یادوں کے بیاباں سے\nایک پکار سی آئی ، میں سنتا ہوا\n\nکس صورت پہ کرتا قیاس عمر بھر کے لیے\nدل کے آئینے میں رہا ، ایک شخص بدلتا ہوا\n\nدن بھر تو رہا سورج سَوا نیزے پہ\nاک شبِ ہجر کیا آئی یہ بھی ڈھلتا ہوا\n\nوہ خواب وہ کاوشیں سب ہوا کی ہوئیں\nاحمد ؔ  یاد ہے ! ایک شخص تھا ہنستا ہوا"},{"slug":"tum-p032","body":"دل جانے پھر تجھ سے ٹوٹا ہے کیوں\nتو ہی مگر اس کا مسیحا ہے کیوں\n\nتیرے ملنے کی خوشی صرف ہم کو ہوئی\nتیرے جانے پہ سارا شہر افسردہ ہے کیوں\n\nوہ شے جو کبھی میسر ہی نہ ہوگی\nایک اسی پہ دل آتا ہے کیوں\n\nعریاں ہیں بدن کے داغ  اور زخم\nغمِ دردِ دل اس قدر پوشیدہ ہے کیوں\n\nجب کوئی راہبر، کوئی جادہِ منزل ہی نہیں\nپھر تو آخر سفر کو چلتا ہے کیوں\n\nمیں نے بھرے فلک میں ایک جس کو چنا\nوہی ستارہ نظر سے گمشدہ ہے کیوں\n\nجب نہیں دل میں کسی کی یاد زندہ\nاحمد ؔ پھر یہ دل دھڑکتا ہے کیوں"},{"slug":"tum-p033","body":"دل میں تیری فرقت کا غم لیے ہوئے\nچل پڑے ہیں چہرے پہ تبسم لئے ہوئے\n\nہم کہ کہاں تھے ان  مقتل گاہوں کے مسافر\nاب دیکھو کھڑے ییں ہاتھ میں علم لیے ہوئے\n\nبلبل کا ہے مزاج  فقط گل پہ انحصار\nگل ہے ہمہ تن کانٹوں کا حجم لیے ہوئے\n\nاب کہاں وہ دل وہ جنوں اور وہ جان جگر\nوہ چلا تو گیا شوق وصل صنم لیے ہوئے\n\nکس طرح  ہوتا  احمد ؔ رسم جدائی پہ اعتبار\nہم جدا ہوئے تھے اپنی ہی قسم لیے ہوئے"},{"slug":"tum-p034","body":"اپنے خوابوں کے فریبوں  کو کیونکر نہ زیاں کرتے\nتم ہی جب نہیں تو کس فرش کو مکاں کرتے\n\nسوچو تو بیچ سفر چھوڑا بھی انھی نے\nجو اگر ساتھ بھی چلتے تو پریشاں کرتے\n\nہم اگر تمہیں نہ ملاتے دہر کے افسانوں سے\nتو یقیناً تمہارے ہر اک پہلو کو آسماں کرتے\n\nیہ درد ، یہ شکوے ، یہ خسارے، سب ہمارے لیے\nتم محبت ہی اگر نہ کرتے تو احساں کرتے\n\nاپنے بس میں ہوتا تو فقط  کچھ پل کے لیے\nاس دلِ ہوش مند کو ذرا دلِ ناداں کرتے\n\nکچھ رات جاگتے اور فقط تم ہی کو سوچتے\nکچھ دن فرصت نکال کر اپنا اور نقصاں کرتے\n\nیہ زندگی تو احمد ؔ یونہی بسر ہو چلی\nاور زندگی بھی ہوتی تو ذکر جاناں کرتے"},{"slug":"tum-p035","body":"کوئی شعر کیا پڑھے، کیا ہی مسکرائے\nکوئی جیے کیا ، جب دل ہی بجھ جائے\n\nاب وہ دور کہاں کہ کسی کو غم سنائیں\nاب وہ لوگ کہاں کہ دل کھلکھلائے\n\nزمانہ ساز تھے، بے خبر تھے، بےوفا نہ تھے\nکوئی اس کو جا کر خدارا یہ سمجھائے\n\nکہیں  تیز دھوپ اتنی کہ جلے جائے اپنا من\nکہیں سرد رات ایسی کہ کوئی ہجر جگائے\n\nسنا تھا کہ دھیرے دھیرے زخم بھرنے لگتے ہیں\nپر تیری فرقت کا غم ہے کہ بڑھتا جائے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
